const frame=document.querySelector('iframe'),out=document.querySelector('#results'),wait=ms=>new Promise(r=>setTimeout(r,ms));let results=[];
const check=(name,ok,detail)=>{results.push({name,pass:!!ok,detail});out.textContent=JSON.stringify({passed:results.filter(r=>r.pass).length,total:results.length,results},null,2);if(!ok)throw Error(name);};
const samePose=(a,b)=>['position','target'].every(k=>a[k].every((x,i)=>Math.abs(x-b[k][i])<1e-8));
async function run(){results=[];const w=frame.contentWindow;for(let i=0;i<200&&!w.AtlasIndustrial?.getState().ready;i++)await wait(100);const A=w.AtlasIndustrial,d=w.document;check('real model ready',A?.getState().ready);A.setState({mode:'story',chapter:0,reduced:true});
 check('six chapter navigation',d.querySelectorAll('#guide-nav button').length===6);check('starting composition shows all meshes',A.inspect().visible===A.inspect().meshCount);check('Chinese mesh aliases',A.getParts().some(p=>p.label==='边箱'));
 const chapter=n=>d.querySelectorAll('#guide-nav button')[n].click();chapter(1);await wait(50);check('context chapter selects luggage',A.getState().group==='luggage');check('spatial labels present',d.querySelectorAll('.model-label:not([hidden])').length>=1);
 chapter(2);check('separation chapter moves parts',A.inspect().offsetMax>.9);const spread=d.querySelector('#story-spread');spread.value=0;spread.dispatchEvent(new w.Event('input',{bubbles:true}));check('story separation reversible',A.inspect().offsetMax<1e-8);spread.value=100;spread.dispatchEvent(new w.Event('input',{bubbles:true}));check('story separation can resume',A.inspect().offsetMax>.9);
 chapter(3);check('detail restores model coordinates',A.inspect().offsetMax<1e-8);const close=A.getState().camera;chapter(0);const wide=A.getState().camera;const dist=p=>Math.hypot(...p.position.map((v,i)=>v-p.target[i]));check('detail camera closer than opening',dist(close)<dist(wide));
 chapter(4);const total=A.inspect().visible,pose=JSON.stringify(A.getState().camera);d.querySelector('#without-luggage').click();check('single variable removes bag meshes',A.inspect().visible<total&&!A.getState().storyLuggage);check('comparison holds camera',JSON.stringify(A.getState().camera)===pose);d.querySelector('#with-luggage').click();check('comparison restored',A.inspect().visible===total);
 chapter(5);check('closing restores all positions and visibility',A.inspect().offsetMax<1e-8&&A.inspect().visible===total);check('closing camera matches opening',JSON.stringify(A.getState().camera)===JSON.stringify(wide));
 const chosen={position:[3,2,-3],target:[0,.7,0]};A.setState({camera:chosen,note:'QA <b>literal note</b>'});const saved=A.getState();A.reset();A.setState(JSON.parse(JSON.stringify(saved)));check('camera and note JSON round trip',samePose(A.getState().camera,chosen)&&A.getState().note===saved.note);check('note is plain textarea text',d.querySelector('#story-note').value===saved.note&&!d.querySelector('#story-note b'));
 let rejected=0;for(const camera of [{position:[NaN,0,0],target:[0,0,0]},{position:[0,0,0],target:[0,0,0]},{position:[100,0,0],target:[0,0,0]},{position:[1,2],target:[0,0,0]}])try{A.setState({camera});}catch{rejected++;}check('malformed camera rejected atomically',rejected===4&&samePose(A.getState().camera,chosen));
 const bookmarkKey='atlas-industrial-bookmark-v2',prior=w.localStorage.getItem(bookmarkKey);try{d.querySelector('#bookmark-save').click();A.reset();d.querySelector('#bookmark-load').click();check('browser bookmark restores full view',A.getState().chapter===5&&samePose(A.getState().camera,chosen));}finally{if(prior===null)w.localStorage.removeItem(bookmarkKey);else w.localStorage.setItem(bookmarkKey,prior);}
 A.setState({mode:'xray',group:'rearwheel',mesh:'tire_rear',camera:chosen});d.querySelector('[data-mode="section"]').click();check('section preserves selected mesh and camera',A.getState().mesh==='tire_rear'&&samePose(A.getState().camera,chosen));d.querySelector('[data-mode="isolate"]').click();check('isolate preserves selection',A.getState().mesh==='tire_rear'&&A.getState().group==='rearwheel');
 A.setState({mode:'story',chapter:2,reduced:false});chapter(3);await wait(1400);check('animated detail uses settled target, not moving parts',samePose(A.getState().camera,close));chapter(0);chapter(2);chapter(5);await wait(1300);check('rapid chapter changes end at complete model',A.getState().chapter===5&&A.inspect().offsetMax<1e-8);d.querySelector('#reset').click();await wait(1300);check('story reset returns to chapter one',A.getState().chapter===0);
 frame.style.width='390px';await wait(300);check('390px viewport has no horizontal page overflow',d.documentElement.scrollWidth<=d.documentElement.clientWidth,{scroll:d.documentElement.scrollWidth,client:d.documentElement.clientWidth});check('mobile chapter buttons remain available',d.querySelectorAll('#guide-nav button').length===6);
 check('loading and rendering diagnostics available',A.inspect().modelReadyMs>0&&A.inspect().drawCalls>0,{modelReadyMs:A.inspect().modelReadyMs,drawCalls:A.inspect().drawCalls,triangles:A.inspect().triangles});frame.style.width='100%';out.textContent+='\nALL NARRATIVE CHECKS PASSED';}
document.querySelector('#run').onclick=()=>run().catch(e=>out.textContent+='\nFAILED: '+e.stack);document.querySelector('#mobile').onclick=()=>frame.style.width='390px';document.querySelector('#desktop').onclick=()=>frame.style.width='100%';
